function audit(){return `<h1>Journal d'audit</h1><p class="sub">Historique des actions, en ajout seul</p><div class="card sc"><table class="rt"><thead><tr><th>Date</th><th>Utilisateur</th><th>Action</th><th>Document</th></tr></thead><tbody>${S.aud.length?S.aud.map(a=>`<tr><td data-l="Date">${ft(a.at)}</td><td data-l="Utilisateur">${esc(a.who)}</td><td class="ti">${esc(a.act)}</td><td data-l="Document">${esc(a.ent)}</td></tr>`).join(''):'<tr><td colspan="4" class="mut">Aucune action enregistrée.</td></tr>'}</tbody></table></div><p><button class="lnk" style="color:var(--mut)" data-a="reset">Réinitialiser les données de l'espace</button></p>`}
function form(m){return `<h1>Nouveau document</h1><p class="sub">Le document est créé en brouillon (version 1)</p><div class="card"><label>Titre<input id="nt"></label><label>Modèle<select id="nm">${Object.keys(TPL).map(t=>`<option>${t}</option>`).join('')}</select></label><label>Service<select id="ns">${SV.map((s,i)=>`<option value="${i}"${i===m.svc?' selected':''}>${s}</option>`).join('')}</select></label><label>Importer un document existant (facultatif)<input id="nf" type="file" accept="${ACC}"></label><p class="mut" style="margin:-8px 0 14px">PDF, Word, Excel, image ou texte · 10 Mo max. Un fichier importé remplace le contenu saisi.</p><div class="lbl">Contenu</div>${EDBAR}${EDIV(bodyH(Object.keys(TPL)[0]))}<div style="height:16px"></div><div class="row"><button data-a="create">Créer le brouillon</button><button class="sec" data-a="go" data-v="docs">Annuler</button></div></div>`}
const lib=(u,g)=>window[g]?Promise.resolve():new Promise((r,j)=>{const s=document.createElement('script');s.src=u;s.onload=r;s.onerror=j;document.head.appendChild(s)});
