const EVL={CREATE:['Brouillon créé','dr'],VERSION:['Nouvelle version','dr'],SUBMIT:['Soumis à la validation','bl'],VALIDATE:['Validé','ok'],REJECT:['Rejeté','rd'],PUBLISH:['Publié','ok'],SIGN:['Lecture signée','bl'],DELEGATE:['Étape déléguée','wa'],COMMENT:['Commentaire','dr']};
function histH(d){const g=[[]];(d.hist||[]).forEach(e=>{if(e.t==='SUBMIT')g.push([]);g[g.length-1].push(e)});
 const out=g.map((es,i)=>{if(!es.length)return'';const b=es.some(e=>e.t==='REJECT')?'<span class="badge rd">Rejeté</span>':es.some(e=>e.t==='PUBLISH')?'<span class="badge ok">Publié</span>':i?'<span class="badge bl">En cours</span>':'<span class="badge dr">Rédaction</span>';
  return `<div class="cy"><h3>${i?'Cycle '+i:'Rédaction'} ${b}</h3>${es.map((e,j)=>{const x=EVL[e.t]||[e.t,'dr'],pv=es[j-1],dd=pv&&(e.t==='VALIDATE'||e.t==='REJECT')?Math.round((e.at-pv.at)/DAY):0;return `<div class="tl ${x[1]}"><b>${x[0]}${e.step?' · '+esc(e.step):''}</b><div class="mut">${esc(un(e.who))} · ${ft(e.at)} · v${e.v}${dd>0?' · '+dd+' j':''}</div>${e.cm?`<div class="cmt${e.t==='REJECT'?' rj':''}">${esc(e.cm)}</div>`:''}</div>`}).join('')}</div>`}).join('');
 return `<div class="card"><h2>Historique du workflow</h2>${out}<label>Ajouter un commentaire<textarea id="cc" style="min-height:70px"></textarea></label><button class="sec" data-a="cmt">Commenter</button></div>`}
const ban=d=>{const r=[...(d.hist||[])].reverse().find(e=>e.t==='REJECT'||e.t==='SUBMIT');return d.status==='BROUILLON'&&r&&r.t==='REJECT'?`<div class="ban"><b>Rejeté par ${esc(un(r.who))}</b> à l'étape « ${esc(r.step)} » · ${ft(r.at)}<div>« ${esc(r.cm)} »</div></div>`:''};
function rep(m){if(m.role!=='ADMIN'&&m.role!=='HSSE')return list(m);const P=S.docs.filter(d=>d.status==='PUBLIE');
 return `<div class="row sp"><div><h1>Rapport de lecture</h1><p class="sub">Qui a lu et signé la version en vigueur</p></div><button class="sec" data-a="rcsv">Exporter (Excel)</button></div>`+(P.map(d=>{const v=lv(d);return `<div class="card sc"><h2>${esc(d.title)} <span class="mut">${d.code} · v${v.n}</span></h2><table class="rt"><tbody>${U.filter(u=>u.svc===d.svc).map(u=>{const s=d.sigs.find(x=>x.u===u.id&&x.v===v.n);return `<tr><td class="ti">${esc(u.name)}</td><td data-l="Statut">${s?'<span class="badge ok">Signé le '+fd(s.at)+'</span>':v.at<D(-7)?'<span class="badge rd">En retard</span>':'<span class="badge wa">En attente</span>'}</td></tr>`}).join('')}</tbody></table></div>`}).join('')||'<p class="mut">Aucun document publié.</p>')}
const tx=v=>{if(v.file)return[v.file.name];const t=document.createElement('div');t.innerHTML=clean(html(v)).replace(/<\/(p|h\d|li|tr|div)>|<br>/gi,'\n');return t.textContent.split('\n').map(x=>x.trim()).filter(Boolean)};
function dif(a,b){const n=a.length,m=b.length,L=Array.from({length:n+1},()=>Array(m+1).fill(0));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)L[i][j]=a[i]===b[j]?L[i+1][j+1]+1:Math.max(L[i+1][j],L[i][j+1]);let i=0,j=0,o='';while(i<n||j<m){if(i<n&&j<m&&a[i]===b[j]){o+='<p>'+esc(a[i])+'</p>';i++;j++}else if(j<m&&(i>=n||L[i][j+1]>=L[i+1][j])){o+='<p class="df a">+ '+esc(b[j])+'</p>';j++}else{o+='<p class="df r">− '+esc(a[i])+'</p>';i++}}return o}
